[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectRoot,[Parameter(Mandatory=$true)][string]$ManifestPath)
$ErrorActionPreference='Stop';$root=(Resolve-Path -LiteralPath $ProjectRoot).Path;if([IO.Path]::IsPathRooted($ManifestPath)){throw 'ManifestPath must be project-relative.'};$rel=$ManifestPath.Replace('\','/').Trim();if($rel.Contains('..')-or $rel -notmatch '^ES/Output/.+\.json$'){throw 'ManifestPath must remain under ES/Output.'};$full=Join-Path $root ($rel.Replace('/',[IO.Path]::DirectorySeparatorChar));if(-not(Test-Path -LiteralPath $full -PathType Leaf)){throw "Resource stage manifest missing: $rel"}
$m=([Text.UTF8Encoding]::new($false,$true).GetString([IO.File]::ReadAllBytes($full))|ConvertFrom-Json);foreach($f in @('schemaVersion','stage','authoritativeLayer','scope','verification')){if([string]::IsNullOrWhiteSpace([string]$m.$f)){throw "Resource manifest missing ${f}."}};if([string]$m.schemaVersion -ne '1'){throw 'Resource manifest schemaVersion must be 1.'};if([string]$m.authoritativeLayer -notin @('authoring','catalog','resource-plan','manifest','provider','release')){throw 'Resource authoritative layer is invalid.'};if([string]$m.stage -notin @('library','book','catalog','plan','manifest','provider','release')){throw 'Resource stage is invalid.'};if([string]$m.verification -match '(?i)pass|success' -and [string]$m.evidenceLevel -notin @('S2','S3','S4','S5','S6')){throw 'Unverified resource stage cannot claim success.'}
Write-Output "PASS: resource pipeline stage manifest is bounded: $rel"
